UPDATE product SET name = #{name}, barcode = #{barcode}, sale_price_cent = #{salePriceCent},
       cost_price_cent = #{costPriceCent}, safety_qty = #{safetyQty}, expire_on = #{expireOn},
       is_active = #{isActive}, spec = #{spec}, category = #{category},
       shelf_life_days = #{shelfLifeDays}, default_supplier_id = #{defaultSupplierId}
WHERE id = #{id}
